INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q492415', 'Battle of Talas', 'The Battle of Talas (Chinese: 怛羅斯戰役; pinyin: Dáluósī Zhànyì; Arabic: معركة نهر طلاس, romanized: Maʿrakat nahr Ṭalās) was an armed confrontation between the Abbasid Caliphate along with the Tibetan Empire against the Tang dynasty and its allies in 751. In July of that year, the Tang and Abbasid armies clashed at the Talas River over control of the regions surrounding the Syr Darya.', 751, 5, NULL, 751, 9, NULL, 'month', 'May 751 – September 751', 73, 'https://en.wikipedia.org/wiki/Battle_of_Talas'),
  ('Q4219257', '1911 Kebin earthquake', 'The 1911 Kebin earthquake, or Chon-Kemin earthquake, struck Russian Turkestan on 3 January. Registering at a moment magnitude of 8.0, it killed 452 people, destroyed more than 770 buildings (which was almost all of the city) in Almaty, Kazakhstan, and resulted in 125 miles (201 km) of surface faulting in the valleys of Chon-Kemin, Chilik and Chon-Aksu.', 1911, 1, 3, NULL, NULL, NULL, 'day', '3 January 1911', 41, 'https://en.wikipedia.org/wiki/1911_Kebin_earthquake'),
  ('Q5908145', '1946 Chatkal earthquake', 'On November 2 of 1946, west Kyrgyzstan (then the Kirghiz Soviet Socialist Republic in the Soviet Union) was struck by a magnitude 7.5–7.6 earthquake, the largest in the republic since 1911. The earthquake''s hypocenter is probably located beneath the Tian Shan Mountains, near the border with Uzbekistan and north of Namangan.', 1946, 11, 2, NULL, NULL, NULL, 'day', '2 November 1946', 34, 'https://en.wikipedia.org/wiki/1946_Chatkal_earthquake'),
  ('Q1122110', 'Tajikistani Civil War', 'The Tajikistani Civil War was an armed conflict in Tajikistan that began in May 1992 and ended in June 1997. Regional groups from the Garm and Gorno-Badakhshan regions of Tajikistan rose up against the newly formed government of President Rahmon Nabiyev, which was dominated by people from the Khujand and Kulob regions.', 1992, 5, 5, 1997, 6, 27, 'day', '5 May 1992 – 27 June 1997', 72, 'https://en.wikipedia.org/wiki/Tajikistani_Civil_War'),
  ('Q6452437', 'Kyrgyzstani presidential referendum, 1994', 'A referendum on President Askar Akayev was held in Kyrgyzstan on 30 January 1994. Voters were asked "Do you confirm that the President of Kyrgyzstan who was democratically elected on 12 October 1991 for 5 years is the President of the Kyrgyz Republic with the right to act as head of state during his term in office?" The result was 97% in favour, with turnout reported to be 96%.', 1994, 1, 30, NULL, NULL, NULL, 'day', '30 January 1994', 37, 'https://en.wikipedia.org/wiki/1994_Kyrgyz_presidential_referendum'),
  ('Q4079409', 'Batken Conflict', 'The Batken conflict (Kyrgyz: Баткен окуясы, romanized: Batken okuyasy, Russian: Баткенские события) was a period of armed clashes between militants of the Islamic Movement of Uzbekistan (IMU) and the Armed Forces of Kyrgyzstan, with support to the former being provided by the Uzbek Ground Forces. It was caused by incursions of IMU militants into Uzbek and Kyrgyz territory from Tajikistan and was in part, centered on the unilateral demarcation of the Kyrgyzstan–Uzbekistan border by Uzbekistan.', 1999, 9, 27, 1999, 9, 27, 'day', '27 September 1999', 48, 'https://en.wikipedia.org/wiki/Batken_conflict'),
  ('Q6452440', 'Kyrgyzstani referendum, 2003', 'A double referendum was held in Kyrgyzstan on 2 February 2003. Voters were asked whether they approved of amendments to the constitution, and whether President Askar Akayev should be allowed to remain in office until 2005.', 2003, 2, 2, NULL, NULL, NULL, 'day', '2 February 2003', 34, 'https://en.wikipedia.org/wiki/2003_Kyrgyz_referendum'),
  ('Q459162', 'Tulip Revolution', 'The Tulip Revolution, also known as the First Kyrgyz Revolution, led to Kyrgyzstan''s then-President Askar Akayev''s fall from power. The revolution began after parliamentary elections on 27 February and 13 March 2005.', 2005, NULL, NULL, 2005, 4, 11, 'year', '2005', 70, 'https://en.wikipedia.org/wiki/Tulip_Revolution'),
  ('Q741126', 'Iran Aseman Airlines Flight 6895', 'Iran Aseman Airlines Flight 6895, was a Boeing 737-200, registered as EX-009, operating a charter flight operated by Itek Air on behalf of Iran Aseman Airlines which crashed on 24 August 2008 (at 20:44 local time) near Manas International Airport in Kyrgyzstan while en route to Imam Khomeini International Airport, Tehran, Iran. It crashed while returning to the airport of origin after experiencing technical difficulties.', 2008, 8, 24, NULL, NULL, NULL, 'day', '24 August 2008', 62, 'https://en.wikipedia.org/wiki/Iran_Aseman_Airlines_Flight_6895'),
  ('Q2470182', '2008 Kyrgyzstan earthquake', 'The 2008 Kyrgyzstan earthquake struck on October 5 at 21:52 local time (15:52 UTC) with a moment magnitude of 6.6, killing 75 people, including 41 children, and injuring 150 people, including 93 children. The center of the earthquake was near the town of Nura, which was destroyed in the quake.', 2008, 10, 5, NULL, NULL, NULL, 'day', '5 October 2008', 45, 'https://en.wikipedia.org/wiki/2008_Kyrgyzstan_earthquake'),
  ('Q236023', 'Kyrgyz Revolution of 2010', 'The 2010 Kyrgyz Revolution, also known as the Second Kyrgyz Revolution, the Melon Revolution, the April Events, or officially as the People''s April Revolution (Kyrgyz: Апрель Элдик революциясы, romanized: Aprel Yeldik revolyutsiyasy), began in April 2010 with the ousting of Kyrgyz president Kurmanbek Bakiyev in the capital Bishkek. It was followed by increased ethnic tension involving Kyrgyz people and Uzbeks in the south of the country, which escalated in June 2010.', 2010, NULL, NULL, 2010, 12, 14, 'year', '2010', 69, 'https://en.wikipedia.org/wiki/2010_Kyrgyz_Revolution'),
  ('Q501106', '2011 Fergana Valley earthquake', 'The 2011 Fergana Valley earthquake affected Uzbekistan, Kyrgyzstan and Tajikistan at 01:35 KGT (19:35 UTC) on 20 July. The dip-slip shock had a moment magnitude of 6.1 and a maximum Mercalli intensity of VIII (Severe).', 2011, 7, 20, NULL, NULL, NULL, 'day', '20 July 2011', 47, 'https://en.wikipedia.org/wiki/2011_Fergana_Valley_earthquake'),
  ('Q99979519', '2020 Kyrgyz Revolution', 'The 2020 Kyrgyz Revolution, also known as the Third Kyrgyz Revolution, began on 5 October 2020, in response to the previous day''s parliamentary election that was perceived by protestors as unfair, with allegations of electoral fraud. The results of the election were annulled on 6 October 2020.', 2020, 10, 5, 2020, 10, 15, 'day', '5 October 2020 – 15 October 2020', 65, 'https://en.wikipedia.org/wiki/2020_Kyrgyz_Revolution');
